import { PRIMITIVE_NAMES, TYPE_NAME } from "./names.js";
import { pluralize } from "./vendor/plur.js";
/** The word a type phrase joins through: `Verified User` joins by its head, `User`. */
export function headOf(typeName) {
    return typeName.slice(typeName.lastIndexOf(" ") + 1);
}
/** Exact State field and subset type references that can evidence an automatic alias. */
export function stateFieldTypeEvidence(declarations) {
    return declarations.flatMap(({ declarationKind, name, fields }) => [
        ...(declarationKind === "subset" ? [headOf(name.text)] : []),
        ...fields.flatMap(({ value }) => value.kind === "named"
            ? [headOf(value.reference.text)]
            : [headOf(value.element.reference.text)]),
    ]);
}
export function exactPluralPair(left, right) {
    return pluralize(left) === right || pluralize(right) === left;
}
/** Whether two words are one in either number, or share a plural as `Ax` and `Axis` do. */
function sameWordInEitherNumber(left, right) {
    return left === right || exactPluralPair(left, right) || pluralize(left) === pluralize(right);
}
/**
 * Whether a subset identifier and another name are one name in code, in either number. The
 * joined qualifiers must match exactly and only the head inflects, so `ActivePerson` names
 * the subset whose identifier is `ActivePeople`, and `Open Ax` and `Open Axis` share
 * `OpenAxes`.
 */
export function sameQualifiedName(prefix, identifier, name) {
    return (identifier === name ||
        (name.length > prefix.length &&
            name.startsWith(prefix) &&
            sameWordInEitherNumber(identifier.slice(prefix.length), name.slice(prefix.length))));
}
/**
 * Relate only exact authored evidence to one owner: a non-element owned set or sequence, or
 * an external type. The pluralizer's output is compared, never inserted into the inventory.
 * A name the Types fence already claims is not a candidate: joining it would make one
 * spelling both joined and declared, which the single type namespace forbids.
 */
export function automaticAliasCandidates(declarations, eligibleStructuralNames, evidenceTypeNames, claimedNames, external, local) {
    const declarationsByName = new Map(declarations.flatMap((declaration) => declaration.declarationKind === "collection"
        ? [[declaration.name.text, declaration]]
        : []));
    const owners = [
        ...[...eligibleStructuralNames].filter((name) => declarationsByName.get(name)?.multiplicity !== "element"),
        ...external,
    ].sort();
    const candidates = [
        ...new Set([...stateFieldTypeEvidence(declarations), ...evidenceTypeNames]),
    ].sort();
    const matches = [];
    for (const candidate of candidates) {
        if (!TYPE_NAME.test(candidate) ||
            eligibleStructuralNames.has(candidate) ||
            claimedNames.has(candidate) ||
            external.has(candidate) ||
            local.has(candidate) ||
            PRIMITIVE_NAMES.has(candidate)) {
            continue;
        }
        for (const owner of owners) {
            if (exactPluralPair(owner, candidate))
                matches.push([candidate, owner]);
        }
    }
    const ownersByCandidate = new Map();
    const candidatesByOwner = new Map();
    for (const [candidate, owner] of matches) {
        const candidateOwners = ownersByCandidate.get(candidate) ?? [];
        candidateOwners.push(owner);
        ownersByCandidate.set(candidate, candidateOwners);
        const ownerCandidates = candidatesByOwner.get(owner) ?? [];
        ownerCandidates.push(candidate);
        candidatesByOwner.set(owner, ownerCandidates);
    }
    const ambiguities = [];
    for (const [candidate, candidateOwners] of ownersByCandidate) {
        if (candidateOwners.length > 1)
            ambiguities.push({ candidates: [candidate], owners: candidateOwners });
    }
    for (const [owner, ownerCandidates] of candidatesByOwner) {
        if (ownerCandidates.length > 1)
            ambiguities.push({ candidates: ownerCandidates, owners: [owner] });
    }
    return {
        aliases: new Map(matches.flatMap(([candidate, owner]) => ownersByCandidate.get(candidate)?.length === 1 && candidatesByOwner.get(owner)?.length === 1
            ? [[candidate, owner]]
            : [])),
        ambiguities,
    };
}
